import json
from urllib.parse import quote
API = 'https://alison.legislature.state.al.us/graphql'
PAGE = 500
Q = ('query sections($limit: Int, $offset: Int) { codesOfAlabama(where: { type: { eq: Section } }, limit: $limit, offset: $offset) { data { codeId displayId title content history effectiveDate } } }')
def sections():
    offset = 0
    while True:
        url = API + '?query=' + quote(Q, safe='') + '&variables=' + quote(json.dumps({'limit': PAGE, 'offset': offset}, separators=(',', ':')), safe='')
        try:
            kind, body = fetch(url)
            d = json.loads(body if isinstance(body, str) else body.decode('utf-8', 'ignore'))
            if d.get('errors'):
                log('the API refused the query: ' + str(d['errors'])[:300]); break   # it dropped `versions` in 2026-10 and this said nothing
            rows = ((d.get('data') or {}).get('codesOfAlabama') or {}).get('data') or []
        except Exception as e:
            log('page failed offset=' + str(offset) + ' ' + repr(e)); break
        for row in rows:
            sid = row.get('displayId')
            text = block_text('<div id="law">' + (row.get('content') or '') + '</div>', id='law')   # the official HTML, read by a real parser
            if sid and len(text) >= 8:
                yield {'id': sid, 'heading': (row.get('title') or sid).strip(), 'text': text,
                       'url': 'https://alison.legislature.state.al.us/code-of-alabama?title=' + sid.split('-', 1)[0] + '&section=' + sid}
        if len(rows) < PAGE:
            break
        offset += len(rows)
